const FAB_ICONS = {
  feed: 'data:image/png;base64,',
  pending: 'data:image/png;base64,',
  admin: 'data:image/png;base64,',
  theme: 'data:image/png;base64,',
  iomHeader: 'data:image/png;base64,',
  secStatusHeader: 'data:image/png;base64,'
};
function renderBranchAttendanceCard(pageId, state) {
  const config = SECTIONS_CONFIG[pageId];
  const offset = getEntryBranchPeriodOffset(pageId);
  const period = getCustomPeriodByOffset(offset);
  const dates = getCustomPeriodDates(period);
  const periodState = getBranchAttendancePeriodState(state, pageId, period.key, true);
  const groups = Object.keys(config.groups);

  const bodyRows = groups.map(groupName => {
    if (!periodState[groupName] || typeof periodState[groupName] !== 'object' || Array.isArray(periodState[groupName])) {
      periodState[groupName] = {};
    }
    const checkedCount = dates.reduce((count, day) => count + (!day.isFuture && isTickValueChecked(periodState[groupName][day.key]) ? 1 : 0), 0);
    const cells = dates.map(day => {
      const val = !day.isFuture ? periodState[groupName][day.key] : false;
      const isTrueTick = val === true || val === 1 || val === '1' || val === 'true';
      return `
        <td class="branch-att-cell ${day.isFriday ? 'is-friday' : ''} ${day.isToday ? 'is-today' : ''} ${day.isFuture ? 'is-future' : ''}">
          <select class="branch-att-select ${isTrueTick ? 'is-ticked' : ''}" data-branch="${groupName}" data-date="${day.key}" ${day.isFuture ? 'disabled' : ''} aria-label="${groupName} ${day.fullLabel}">
            <option value="" ${!val ? 'selected' : ''}></option>
            <option value="true" ${isTrueTick ? 'selected' : ''}>âœ“</option>
            <option value="1hr" ${val === '1hr' ? 'selected' : ''}>1hr</option>
            <option value="2hr" ${val === '2hr' ? 'selected' : ''}>2hr</option>
            <option value="3hr" ${val === '3hr' ? 'selected' : ''}>3hr</option>
            <option value="4hr" ${val === '4hr' ? 'selected' : ''}>4hr</option>
            <option value="5hr" ${val === '5hr' ? 'selected' : ''}>5hr</option>
            <option value="6hr" ${val === '6hr' ? 'selected' : ''}>6hr</option>
            <option value="7hr" ${val === '7hr' ? 'selected' : ''}>7hr</option>
            <option value="8hr" ${val === '8hr' ? 'selected' : ''}>8hr</option>
          </select>
        </td>`;
    }).join('');

    return `
      <tr>
        <td class="branch-name-cell">
          <div class="branch-name-main">${groupName}</div>
          <div class="branch-name-sub">${checkedCount}/${dates.length} days ticked</div>
        </td>
        ${cells}
      </tr>`;
  }).join('');

  const headerCells = dates.map(day => `
    <th class="branch-date-head ${day.isFriday ? 'is-friday' : ''} ${day.isToday ? 'is-today' : ''} ${day.isFuture ? 'is-future' : ''}">
      <span class="branch-day-no">${day.dayNumber}</span>
      <span class="branch-weekday">${day.weekday}</span>
    </th>
  `).join('');

  const checkedTotal = groups.reduce((total, groupName) => {
    const dayMap = periodState[groupName] || {};
    return total + dates.reduce((count, day) => count + (!day.isFuture && isTickValueChecked(dayMap[day.key]) ? 1 : 0), 0);
  }, 0);

  const card = document.createElement('div');
  card.className = 'glass-card branch-att-card';
  card.innerHTML = `
    <div class="branch-att-header">
      <div>
        <div class="branch-att-eyebrow">Overtime Monthly Tick Sheet</div>
        <h3 class="branch-att-title">Overtime Attendance â€” ${period.monthName}</h3>
        <p class="branch-att-range">${period.rangeLabel} Â· ${period.label}</p>
      </div>
      <div class="branch-period-actions no-print">
        <button class="branch-period-btn" data-branch-period-step="-1" type="button">â€¹ Previous</button>
        <button class="branch-period-btn" data-branch-period-step="0" type="button">Current</button>
        <button class="branch-period-btn" data-branch-period-step="1" type="button">Next â€º</button>
      </div>
    </div>
    <div class="branch-att-summary">
      <span>${groups.length} sections</span>
      <span>${dates.length} days</span>
      <span>${checkedTotal} ticks selected</span>
    </div>
    <div class="table-container branch-table-wrap">
      <table class="branch-att-table">
        <thead>
          <tr>
            <th class="branch-name-head">Section Name</th>
            ${headerCells}
          </tr>
        </thead>
        <tbody>${bodyRows}</tbody>
      </table>
    </div>
  `;

  return card;
}

function bindBranchAttendanceControls(pageId, state) {
  document.querySelectorAll('[data-branch-period-step]').forEach(btn => {
    btn.addEventListener('click', () => {
      const step = parseInt(btn.getAttribute('data-branch-period-step'), 10) || 0;
      const nextOffset = step === 0 ? 0 : getEntryBranchPeriodOffset(pageId) + step;
      setEntryBranchPeriodOffset(pageId, nextOffset);
      _renderEntryContent(pageId);
    });
  });

  document.querySelectorAll('.branch-att-select').forEach(input => {
    input.addEventListener('change', e => {
      if (e.target.value === 'true') {
        e.target.classList.add('is-ticked');
      } else {
        e.target.classList.remove('is-ticked');
      }
      const period = getCustomPeriodByOffset(getEntryBranchPeriodOffset(pageId));
      const branchName = e.target.getAttribute('data-branch');
      const dateKey = e.target.getAttribute('data-date');
      const periodState = getBranchAttendancePeriodState(state, pageId, period.key, true);
      if (!periodState[branchName] || typeof periodState[branchName] !== 'object' || Array.isArray(periodState[branchName])) {
        periodState[branchName] = {};
      }
      let val = e.target.value;
      if (val === "true") val = true;
      if (val === "") val = false;
      periodState[branchName][dateKey] = val;
      const row = e.target.closest('tr');
      const sub = row?.querySelector('.branch-name-sub');
      if (sub) {
        const checkedCount = Array.from(row.querySelectorAll('.branch-att-select')).filter(s => s.value !== "").length;
        sub.textContent = `${checkedCount}/${getCustomPeriodDates(period).length} days ticked`;
      }
      const summary = document.querySelector('.branch-att-summary span:last-child');
      if (summary) {
        const totalCount = Array.from(document.querySelectorAll('.branch-att-select')).filter(s => s.value !== "").length;
        summary.textContent = `${totalCount} ticks selected`;
      }
    });
  });
  scrollBranchAttendanceToToday();
}

function scrollBranchAttendanceToToday(root = document) {
  root.querySelectorAll('.branch-table-wrap').forEach(wrap => {
    const todayCell = wrap.querySelector('.branch-date-head.is-today');
    if (!todayCell) return;
    const stickyWidth = wrap.querySelector('.branch-name-head')?.offsetWidth || 0;
    const targetLeft = Math.max(0, todayCell.offsetLeft - stickyWidth - 16);
    requestAnimationFrame(() => {
      wrap.scrollLeft = targetLeft;
    });
  });
}

