      return `<td class="branch-att-cell ${day.isFriday ? 'is-friday' : ''} ${day.isToday ? 'is-today' : ''} ${day.isFuture ? 'is-future' : ''}"><span class="branch-overview-mark ${checked ? 'checked' : ''} ${day.isFuture ? 'future-mark' : ''}">${checked ? 'âœ“' : ''}</span></td>`;
