window.closeBranchAttendanceModal = function () {
  const modal = document.getElementById('branch-att-modal');
  if (!modal) return;
  modal.classList.remove('is-open');
  setTimeout(() => modal.remove(), 260);
};

function renderBranchAttendanceModalContent() {
  const content = document.getElementById('branch-modal-content');
  if (!content) return;
  content.innerHTML = buildBranchAttendanceOverviewHtml((localDashboardState || getAppState()), getCustomPeriodByOffset(window.branchAttendanceModalOffset || 0));
  bindBranchAttendanceModalControls();
}

function bindBranchAttendanceModalControls() {
  document.querySelectorAll('[data-branch-modal-step]').forEach(btn => {
    btn.addEventListener('click', () => {
      const step = parseInt(btn.getAttribute('data-branch-modal-step'), 10) || 0;
      window.branchAttendanceModalOffset = step === 0 ? 0 : (window.branchAttendanceModalOffset || 0) + step;
      renderBranchAttendanceModalContent();
    });
  });
  scrollBranchAttendanceToToday(document.getElementById('branch-att-modal') || document);
}

function buildOvertimeAttendanceJpgHtml(state, period) {
  const dates = getCustomPeriodDates(period);
  const rows = getAllBranchAttendanceRows();
  const clock = getClockSnapshot();
  const bodyRows = rows.map(row => {
    const periodState = getBranchAttendancePeriodState(state, row.pageId, period.key, false) || {};
    const dayMap = periodState[row.groupName] || {};
    const dateCells = dates.map(day => {
      const val = !day.isFuture ? dayMap[day.key] : false;
      const isTrueTick = val === true || val === 1 || val === '1' || val === 'true';
      const hasValue = isTrueTick || (typeof val === 'string' && val.endsWith('hr'));
      let content = '';
      if (isTrueTick) content = 'âœ“';
      else if (hasValue) content = val;
      return `<td class="${day.isFriday ? 'friday' : ''} ${day.isFuture ? 'future' : ''} ${hasValue ? 'checked' : ''}">${hasValue ? `<span class="ot-export-check">${content}</span>` : ''}</td>`;
    }).join('');
    return `
      <tr>
        <td class="ot-export-branch">
          <strong>${row.groupName}</strong>
        </td>
        ${dateCells}
      </tr>`;
  }).join('');

  const headerCells = dates.map(day => `
    <th class="${day.isFriday ? 'friday' : ''} ${day.isToday ? 'today' : ''} ${day.isFuture ? 'future' : ''}">
      <b>${day.dayNumber}</b>
      <span>${day.weekday}</span>
    </th>
  `).join('');

  return `
    <div class="ot-export-sheet">
      <div class="ot-export-watermark"></div>
      <div class="ot-export-head">
        <div>
          <div class="ot-export-company">MEP FAN LTD.</div>
          <h1>Overtime Attendance</h1>
          <p>${period.rangeLabel} Â· ${period.label}</p>
        </div>
        <div class="ot-export-clock-shell">
          ${buildExportClockMarkup(clock, OVERTIME_EXPORT_THEME, {
            analogSize: 90,
            widgetPadding: '0.64rem 0.84rem',
            width: '188px',
            digitalSize: '1.42rem',
            dateSize: '0.8rem',
            ampmSize: '0.7rem'
          })}
        </div>
      </div>

      <table class="ot-export-table">
        <thead>
          <tr>
            <th class="ot-export-name-head">Section Name</th>
            ${headerCells}
          </tr>
        </thead>
        <tbody>${bodyRows}</tbody>
      </table>
    </div>`;
}

