  titleRow3.innerHTML = `<th colspan="17" style="font-size: 11pt; text-align: center; font-weight: bold; background-color: #f0fdf4; color: #047857; border: .5pt solid #cbd5e1; vertical-align: middle; font-family: 'Times New Roman', Times, serif;">IOM (Inter-Office Memorandum) â€” Overtime Log</th>`;
  
  const spacerRow = document.createElement('tr');
  spacerRow.style.height = '6pt';
  spacerRow.innerHTML = `<th colspan="17" style="background-color: #ffffff; border: none;"></th>`;

  thead.insertBefore(spacerRow, thead.firstChild);
  thead.insertBefore(titleRow3, thead.firstChild);
  thead.insertBefore(titleRow2, thead.firstChild);
  thead.insertBefore(titleRow1, thead.firstChild);

  // Add signature rows to tfoot
  const tfoot = exportTable.querySelector('tfoot');
  const emptyRow1 = document.createElement('tr');
