window.downloadIomJpg = function() {
  if (typeof html2canvas === 'undefined') {
    alert("Missing html2canvas script!");
    return;
  }
  const reportSection = document.getElementById('iom-dashboard-report');
  if (!reportSection) return;
  
  // Show print-only elements temporarily
  const printTitle = reportSection.querySelector('.iom-export-title');
  const printFooter = reportSection.querySelector('.iom-export-footer');
  if (printTitle) printTitle.style.display = 'block';
  if (printFooter) printFooter.style.display = 'flex';
  
  // Hide no-print elements
  const noPrintEls = reportSection.querySelectorAll('.no-print');
  noPrintEls.forEach(el => el.style.display = 'none');
  
  const inputs = reportSection.querySelectorAll('input');
  inputs.forEach(inp => inp.style.display = 'none');
  const printSpans = reportSection.querySelectorAll('.print-only');
  printSpans.forEach(span => {
    if (span !== printTitle && span !== printFooter) span.style.display = 'inline';
  });
  
  const originalBackground = reportSection.style.background;
  reportSection.style.background = '#ffffff';

  html2canvas(reportSection, { scale: 2, backgroundColor: '#ffffff' }).then(canvas => {
    // Restore
    reportSection.style.background = originalBackground;
    if (printTitle) printTitle.style.display = 'none';
    if (printFooter) printFooter.style.display = 'none';
    noPrintEls.forEach(el => el.style.display = '');
    inputs.forEach(inp => inp.style.display = '');
    printSpans.forEach(span => {
      if (span !== printTitle && span !== printFooter) span.style.display = 'none';
    });
    
    const period = getCustomPeriodByOffset(getIomDashboardPeriodOffset());
    const link = document.createElement('a');
    link.download = `IOM_Report_${period.label.replace(/\s+/g, '_')}.jpg`;
    link.href = canvas.toDataURL('image/jpeg', 0.92);
    link.click();
  });
};

window.downloadOvertimeAttendanceExcel = function () {
  if (typeof window.syncLiveDataToAppState === 'function') window.syncLiveDataToAppState();
  const periodOffset = document.getElementById('overtime-dashboard-report')
    ? getOvertimeDashboardPeriodOffset()
    : (window.branchAttendanceModalOffset || 0);
  const period = getCustomPeriodByOffset(periodOffset);
  
  const exportNode = document.createElement('div');
  exportNode.innerHTML = buildOvertimeAttendanceJpgHtml((localDashboardState || getAppState()), period);
  
  const table = exportNode.querySelector('.ot-export-table');
  if (!table) return;

  // Apply inline styles to ensure Excel renders formatting correctly
  table.style.borderCollapse = 'collapse';
  table.style.fontFamily = '"Times New Roman", serif';
  table.querySelectorAll('th, td').forEach(el => {
    el.style.border = '1px solid #000000';
    el.style.padding = '4px';
    if (!el.style.textAlign) el.style.textAlign = 'center';
  });
  table.querySelectorAll('th').forEach(th => {
    th.style.backgroundColor = '#e2e8f0';
    th.style.fontWeight = 'bold';
  });
  table.querySelectorAll('.ot-export-name-head, .ot-export-branch').forEach(el => {
    el.style.textAlign = 'left';
    el.style.fontWeight = 'bold';
  });
  table.querySelectorAll('.friday').forEach(el => {
    el.style.color = 'red';
    el.style.backgroundColor = '#fee2e2';
  });
  table.querySelectorAll('.future').forEach(el => {
    el.style.backgroundColor = '#f1f5f9';
    el.style.color = '#94a3b8';
  });
  table.querySelectorAll('.checked').forEach(el => {
    el.style.backgroundColor = '#ccfbf1';
  });
  table.querySelectorAll('.ot-export-total').forEach(el => {
    el.style.fontWeight = 'bold';
  });

  // Calculate and append Total (Hrs) column for Excel
  const trHead = table.querySelector('thead tr');
  if (trHead) {
    const th = document.createElement('th');
    th.innerText = 'Total (Hrs)';
    th.style.backgroundColor = '#e2e8f0';
    th.style.fontWeight = 'bold';
    th.style.border = '1px solid #000000';
    th.style.padding = '4px';
    trHead.appendChild(th);
  }

  table.querySelectorAll('tbody tr').forEach(tr => {
    let totalHrs = 0;
    tr.querySelectorAll('td').forEach((td, index) => {
      if (index === 0) return; // Skip section name column
      const text = td.innerText || '';
      if (text.includes('hr')) {
        const hrs = parseInt(text.replace('hr', '').trim(), 10);
        if (!isNaN(hrs)) totalHrs += hrs;
      }
    });

    const td = document.createElement('td');
    td.innerText = totalHrs > 0 ? `${totalHrs}hr` : '';
    td.style.border = '1px solid #000000';
    td.style.padding = '4px';
    td.style.textAlign = 'center';
    td.style.fontWeight = 'bold';
    td.style.backgroundColor = '#f8fafc'; // light gray for total
    tr.appendChild(td);
  });

  const html = `
    <html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
    <head>
      <meta charset="utf-8" />
    </head>
    <body>
      <h2 style="font-family: 'Times New Roman', serif;">Overtime Attendance - ${period.rangeLabel}</h2>
      ${table.outerHTML}
    </body>
    </html>
  `;
  
  const blob = new Blob([html], { type: 'application/vnd.ms-excel' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.download = `overtime-attendance-${period.monthName.toLowerCase()}-${period.end.getFullYear()}.xls`;
  link.href = url;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
};

window.downloadOvertimeAttendanceJpg = function () {
  return runWithOriginalExportMotion(downloadOvertimeAttendanceJpgOriginal);
};

function downloadOvertimeAttendanceJpgOriginal() {
  const periodOffset = document.getElementById('overtime-dashboard-report')
    ? getOvertimeDashboardPeriodOffset()
    : (window.branchAttendanceModalOffset || 0);
  const period = getCustomPeriodByOffset(periodOffset);
  const exportNode = document.createElement('div');
  exportNode.className = 'ot-export-canvas';
  exportNode.innerHTML = buildOvertimeAttendanceJpgHtml((localDashboardState || getAppState()), period);
  document.body.appendChild(exportNode);
  applyThemeToOvertimeExport(exportNode.querySelector('.ot-export-sheet'));

  if (typeof html2canvas === 'undefined') {
    alert("Missing html2canvas script! Please ensure html2canvas is loaded.");
    exportNode.remove();
    return;
  }

  return html2canvas(exportNode.querySelector('.ot-export-sheet'), {
    scale: Math.max(2, Math.min(3, window.devicePixelRatio || 2)),
    backgroundColor: '#ffffff',
    useCORS: true,
    scrollX: 0,
    scrollY: 0
  }).then(canvas => {
    const link = document.createElement('a');
    link.download = `overtime-attendance-${period.monthName.toLowerCase()}-${period.end.getFullYear()}.jpg`;
    link.href = canvas.toDataURL('image/jpeg', 0.98);
    link.click();
    exportNode.remove();
  }).catch(err => {
    console.error('Overtime attendance JPG export failed:', err);
    exportNode.remove();
    alert('Export failed. Please try again.');
  });
}

